      end

      addr_hit[5]: begin
        reg_rdata_next[1:0] = status_speed_qs;
        reg_rdata_next[2] = status_speed_valid_qs;
        reg_rdata_next[3] = status_tx_enabled_qs;
        reg_rdata_next[4] = status_rx_enabled_qs;
        reg_rdata_next[5] = status_cfg_pending_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[31:0] = tx_underflow_count_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[31:0] = rx_bad_frame_count_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[31:0] = rx_bad_fcs_count_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // shadow busy
  logic shadow_busy;
  assign shadow_busy = 1'b0;

  // register busy
  assign reg_busy = shadow_busy;

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface

  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit), clk_i, !rst_ni)

endmodule
